+                        System.getProperties().remove("Foo");
+                    }
+                    return null;
+                }
+            });
+            createConfigFuture.get();
+            running.set(false);
+            changeSystemPropertyFuture.get();
+        }
+        finally {
+            exe.shutdown();
+        }
+    }
+
+
